package com.fakelegacy.order.web;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import com.fakelegacy.order.client.CatalogClient;
import com.fakelegacy.order.client.CustomerClient;
import com.fakelegacy.order.client.ProductSnapshot;
import com.fakelegacy.order.client.RemoteResult;
import com.fakelegacy.order.domain.Cart;
import com.fakelegacy.order.domain.CartLine;
import com.fakelegacy.order.pricing.PricingConstants;
import com.fakelegacy.order.pricing.TaxUtils;
import com.fakelegacy.order.repo.CartRepository;
import com.fakelegacy.order.web.ApiRequests.CartCreateRequest;
import com.fakelegacy.order.web.ApiRequests.CartItemRequest;

@RestController
public class CartController {

    @Autowired
    private CartRepository carts;
    @Autowired
    private CustomerClient customerClient;
    @Autowired
    private CatalogClient catalogClient;

    // O1
    @PostMapping("/carts")
    public ResponseEntity<Object> create(@RequestBody CartCreateRequest req) {
        if (req == null || req.customerId() == null) {
            return ResponseEntity.badRequest().body(message("customerId is required"));
        }
        RemoteResult customer = customerClient.getCustomer(req.customerId());
        if (!customer.isOk()) {
            return ResponseEntity.badRequest().body(message("unknown customer: " + req.customerId()));
        }
        Cart cart = new Cart();
        cart.setCustomerId(req.customerId());
        cart.setStatus(Cart.OPEN);
        cart.setCreatedAt(LocalDateTime.now());
        return ResponseEntity.status(HttpStatus.CREATED).body(carts.save(cart));
    }

    // O2: qty is the new quantity of the line, 0 removes it
    @PostMapping("/carts/{id}/items")
    public ResponseEntity<Object> setItem(@PathVariable("id") Long id, @RequestBody CartItemRequest req) {
        Cart cart = carts.findById(id).orElse(null);
        if (cart == null) {
            return ResponseEntity.notFound().build();
        }
        if (!Cart.OPEN.equals(cart.getStatus())) {
            return ResponseEntity.badRequest().body(message("cart is closed"));
        }
        if (req == null || req.sku() == null || req.qty() == null || req.qty() < 0) {
            return ResponseEntity.badRequest().body(message("sku and qty >= 0 are required"));
        }
        if (req.qty() == 0) {
            CartLine existing = cart.findLine(req.sku());
            if (existing != null) {
                cart.getLines().remove(existing);
            }
        } else {
            Map<String, Object> raw = catalogClient.getProduct(req.sku());
            if (raw == null) {
                return ResponseEntity.badRequest().body(message("unknown product: " + req.sku()));
            }
            if (!ProductSnapshot.from(raw).isActive()) {
                return ResponseEntity.badRequest().body(message("product is not sold anymore: " + req.sku()));
            }
            CartLine existing = cart.findLine(req.sku());
            if (existing != null) {
                existing.setQuantity(req.qty());
            } else {
                cart.getLines().add(new CartLine(cart, req.sku(), req.qty()));
            }
        }
        return ResponseEntity.ok(carts.save(cart));
    }

    // O3: totals are estimates (no promo, no shipping), same rules as the checkout
    @GetMapping("/carts/{id}")
    public ResponseEntity<Object> get(@PathVariable("id") Long id) {
        Cart cart = carts.findById(id).orElse(null);
        if (cart == null) {
            return ResponseEntity.notFound().build();
        }
        String tier = "STANDARD";
        RemoteResult customer = customerClient.getCustomer(cart.getCustomerId());
        if (customer.isOk()) {
            tier = String.valueOf(customer.getBody().get("tier"));
        }

        BigDecimal rate = PricingConstants.tierRate(tier);
        BigDecimal totalHt = BigDecimal.ZERO.setScale(2);
        BigDecimal totalTtc = BigDecimal.ZERO.setScale(2);
        List<Map<String, Object>> lines = new ArrayList<>();
        for (CartLine cl : cart.getLines()) {
            Map<String, Object> raw = catalogClient.getProduct(cl.getSku());
            Map<String, Object> line = new LinkedHashMap<>();
            line.put("sku", cl.getSku());
            line.put("quantity", cl.getQuantity());
            if (raw == null) {
                line.put("unavailable", true);
                lines.add(line);
                continue;
            }
            ProductSnapshot p = ProductSnapshot.from(raw);
            BigDecimal unit = p.isOnSale() ? p.getSalePrice() : p.getBasePrice();
            BigDecimal gross = TaxUtils.round2(unit.multiply(BigDecimal.valueOf(cl.getQuantity())));
            BigDecimal ht = gross;
            if (!p.isOnSale()) {
                BigDecimal tierDiscount = TaxUtils.round2(gross.multiply(rate));
                BigDecimal afterTier = gross.subtract(tierDiscount);
                BigDecimal volumeDiscount = BigDecimal.ZERO.setScale(2);
                if (cl.getQuantity() >= PricingConstants.VOLUME_MIN_QTY) {
                    volumeDiscount = TaxUtils.round2(afterTier.multiply(PricingConstants.VOLUME_RATE));
                }
                ht = afterTier.subtract(volumeDiscount);
            }
            BigDecimal vat = TaxUtils.vatRateFor(p.getCategory());
            BigDecimal ttc = TaxUtils.withVat(ht, vat);
            line.put("unitBasePrice", p.getBasePrice());
            line.put("onSale", p.isOnSale());
            line.put("estimatedLineHt", ht);
            line.put("vatRate", vat);
            line.put("estimatedLineTtc", ttc);
            lines.add(line);
            totalHt = totalHt.add(ht);
            totalTtc = totalTtc.add(ttc);
        }

        Map<String, Object> res = new LinkedHashMap<>();
        res.put("id", cart.getId());
        res.put("customerId", cart.getCustomerId());
        res.put("status", cart.getStatus());
        res.put("tier", tier);
        res.put("lines", lines);
        res.put("estimatedGoodsHt", totalHt);
        res.put("estimatedGoodsTtc", totalTtc);
        return ResponseEntity.ok(res);
    }

    private Map<String, Object> message(String text) {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("message", text);
        return m;
    }
}
